<?php
/** Shared EMS/TMS messaging stored in aurora_db. */
class CommunicationController {
    private $db;
    private $emojis = array('👍','❤️','😂','😮','😢','🎉');
    private $emojiCodes = array('👍'=>'like','❤️'=>'heart','😂'=>'laugh','😮'=>'wow','😢'=>'sad','🎉'=>'celebrate');
    public function __construct($db){$this->db=$db;}
    public static function ensureSchema($db){
        $ok=$db->query("CREATE TABLE IF NOT EXISTS aurora_internal_messages (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,sender_system VARCHAR(8) NOT NULL,sender_user_id BIGINT UNSIGNED NOT NULL,recipient_system VARCHAR(8) NOT NULL,recipient_user_id BIGINT UNSIGNED NOT NULL,content TEXT NOT NULL,topic_tag VARCHAR(80) NULL,reply_to_id BIGINT UNSIGNED NULL,message_type VARCHAR(16) NOT NULL DEFAULT 'text',read_at DATETIME NULL,created_at DATETIME NOT NULL,updated_at DATETIME NOT NULL,KEY idx_message_sender(sender_system,sender_user_id,created_at),KEY idx_message_recipient(recipient_system,recipient_user_id,read_at,created_at),KEY idx_message_thread(sender_system,sender_user_id,recipient_system,recipient_user_id,created_at)) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci");
        $columns=array('reply_to_id'=>"BIGINT UNSIGNED NULL AFTER topic_tag",'message_type'=>"VARCHAR(16) NOT NULL DEFAULT 'text' AFTER reply_to_id");
        foreach($columns as $name=>$definition){$check=$db->query("SHOW COLUMNS FROM aurora_internal_messages LIKE '{$name}'");if($check&&$check->num_rows===0)$ok=$ok&&$db->query("ALTER TABLE aurora_internal_messages ADD COLUMN {$name} {$definition}");}
        $ok=$ok&&$db->query("CREATE TABLE IF NOT EXISTS aurora_message_attachments (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT PRIMARY KEY,message_id BIGINT UNSIGNED NOT NULL,original_name VARCHAR(255) NOT NULL,stored_name VARCHAR(255) NOT NULL,mime_type VARCHAR(120) NOT NULL,size_bytes BIGINT UNSIGNED NOT NULL,created_at DATETIME NOT NULL,UNIQUE KEY uq_attachment_message(message_id),KEY idx_attachment_message(message_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci");
        $ok=$ok&&$db->query("CREATE TABLE IF NOT EXISTS aurora_message_reactions (message_id BIGINT UNSIGNED NOT NULL,actor_system VARCHAR(8) NOT NULL,actor_user_id BIGINT UNSIGNED NOT NULL,emoji VARCHAR(16) NOT NULL,created_at DATETIME NOT NULL,PRIMARY KEY(message_id,actor_system,actor_user_id,emoji),KEY idx_reaction_message(message_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8 COLLATE=utf8_unicode_ci");
        return (bool)$ok;
    }
    private function root(){return dirname(dirname(dirname(dirname(dirname(dirname(__FILE__))))));}
    private function uploadDir(){return $this->root().DIRECTORY_SEPARATOR.'uploads'.DIRECTORY_SEPARATOR.'communications';}
    private function parsePartner($ref){if(!preg_match('/^(tms|ems):(\d+)$/',(string)$ref,$m))jsonResponse(array('success'=>false,'message'=>'Người nhận không hợp lệ.'),422);return array('system'=>$m[1],'id'=>(int)$m[2]);}
    private function contacts($me){
        $items=array();$r=$this->db->query("SELECT id,full_name AS name,role,email,theater_id FROM users WHERE status='active' AND role<>'customer' ORDER BY full_name");
        if($r)while($x=$r->fetch_assoc()){if((int)$x['id']===$me['id'])continue;$x['system']='tms';$x['ref']='tms:'.$x['id'];$x['department']='Theater Management System';$items[]=$x;}
        $r=$this->db->query("SELECT id,name,role,email,department,avatar FROM ems_users WHERE status='active' ORDER BY name");if($r)while($x=$r->fetch_assoc()){$x['system']='ems';$x['ref']='ems:'.$x['id'];$items[]=$x;}return $items;
    }
    private function thread($mid,$ps,$pid){return "((m.sender_system='tms' AND m.sender_user_id={$mid} AND m.recipient_system='{$ps}' AND m.recipient_user_id={$pid}) OR (m.sender_system='{$ps}' AND m.sender_user_id={$pid} AND m.recipient_system='tms' AND m.recipient_user_id={$mid}))";}
    private function messages($mid,$ps,$pid){
        $rows=array();$thread=$this->thread($mid,$ps,$pid);$sql="SELECT m.*,a.id attachment_id,a.original_name,a.mime_type,a.size_bytes,r.content reply_content,r.message_type reply_message_type,r.sender_system reply_sender_system FROM aurora_internal_messages m LEFT JOIN aurora_message_attachments a ON a.message_id=m.id LEFT JOIN aurora_internal_messages r ON r.id=m.reply_to_id WHERE {$thread} ORDER BY m.id ASC LIMIT 500";
        $r=$this->db->query($sql);$ids=array();if($r)while($x=$r->fetch_assoc()){$x['mine']=$x['sender_system']==='tms'&&(int)$x['sender_user_id']===$mid;$x['attachment']=$x['attachment_id']?array('id'=>(int)$x['attachment_id'],'name'=>$x['original_name'],'mime'=>$x['mime_type'],'size'=>(int)$x['size_bytes']):null;$x['reply']=$x['reply_to_id']?array('id'=>(int)$x['reply_to_id'],'content'=>$x['reply_content'],'type'=>$x['reply_message_type'],'sender_system'=>$x['reply_sender_system']):null;$x['reactions']=array();$ids[]=(int)$x['id'];$rows[(int)$x['id']]=$x;}
        if($ids){$idList=implode(',',$ids);$rr=$this->db->query("SELECT message_id,emoji,COUNT(*) total,MAX(actor_system='tms' AND actor_user_id={$mid}) mine FROM aurora_message_reactions WHERE message_id IN ({$idList}) GROUP BY message_id,emoji ORDER BY MIN(created_at)");if($rr)while($x=$rr->fetch_assoc()){$symbol=array_search($x['emoji'],$this->emojiCodes,true);$rows[(int)$x['message_id']]['reactions'][]=array('emoji'=>$symbol?$symbol:$x['emoji'],'count'=>(int)$x['total'],'mine'=>(bool)$x['mine']);}}
        return array_values($rows);
    }
    private function saveUpload($file){
        if(!$file||$file['error']!==UPLOAD_ERR_OK)jsonResponse(array('success'=>false,'message'=>'Tệp tải lên không hợp lệ.'),422);if((int)$file['size']>25*1024*1024)jsonResponse(array('success'=>false,'message'=>'Tệp không được vượt quá 25 MB.'),422);
        $mime=$file['type'];
        if(function_exists('finfo_open')){
            $f=finfo_open(FILEINFO_MIME_TYPE);
            if($f){
                $detected=finfo_file($f,$file['tmp_name']);
                finfo_close($f);
                if($detected) $mime=$detected;
            }
        }
        $blocked=array('text/html','image/svg+xml','application/x-php','application/x-msdownload');if(in_array($mime,$blocked,true))jsonResponse(array('success'=>false,'message'=>'Loại tệp này không được phép.'),422);
        $dir=$this->uploadDir();if(!is_dir($dir)&&!mkdir($dir,0775,true))jsonResponse(array('success'=>false,'message'=>'Không thể tạo thư mục lưu tệp.'),500);$ext=strtolower(pathinfo($file['name'],PATHINFO_EXTENSION));
        $random=md5(uniqid(mt_rand(),true).microtime());
        if(function_exists('random_bytes')) $random=bin2hex(random_bytes(18));
        $stored=$random.($ext?'.'.preg_replace('/[^a-z0-9]/','',$ext):'');if(!move_uploaded_file($file['tmp_name'],$dir.DIRECTORY_SEPARATOR.$stored))jsonResponse(array('success'=>false,'message'=>'Không thể lưu tệp đính kèm.'),500);
        return array('original'=>substr(basename(str_replace('\\','/',$file['name'])),0,255),'stored'=>$stored,'mime'=>$mime?$mime:'application/octet-stream','size'=>(int)$file['size'],'type'=>strpos($mime,'image/')===0?'image':(strpos($mime,'audio/')===0?'audio':'file'));
    }
    public function download(){
        $user=requireAdmin();if(!self::ensureSchema($this->db))jsonResponse(array('success'=>false,'message'=>'Không thể đọc dữ liệu tệp.'),500);$id=(int)(isset($_GET['id'])?$_GET['id']:0);$mid=(int)$user['id'];$r=$this->db->query("SELECT a.* FROM aurora_message_attachments a JOIN aurora_internal_messages m ON m.id=a.message_id WHERE a.id={$id} AND ((m.sender_system='tms' AND m.sender_user_id={$mid}) OR (m.recipient_system='tms' AND m.recipient_user_id={$mid})) LIMIT 1");$x=$r?$r->fetch_assoc():null;if(!$x)jsonResponse(array('success'=>false,'message'=>'Không tìm thấy tệp hoặc bạn không có quyền tải.'),404);$path=$this->uploadDir().DIRECTORY_SEPARATOR.$x['stored_name'];if(!is_file($path))jsonResponse(array('success'=>false,'message'=>'Tệp không còn tồn tại trên máy chủ.'),404);$name=str_replace(array("\r","\n",'"'),'',basename($x['original_name']));header('Content-Type: '.$x['mime_type']);header('Content-Length: '.filesize($path));header("Content-Disposition: attachment; filename*=UTF-8''".rawurlencode($name));readfile($path);exit;
    }
    public function handle($method){
        $user=requireAdmin();$mid=(int)$user['id'];if(!self::ensureSchema($this->db))jsonResponse(array('success'=>false,'message'=>'Không thể khởi tạo kênh trao đổi trong aurora_db: '.$this->db->error),500);
        if($method==='GET'&&empty($_GET['partner'])){$contacts=$this->contacts(array('id'=>$mid));$refs=array();$unread=array();$r=$this->db->query("SELECT IF(sender_system='tms' AND sender_user_id={$mid},CONCAT(recipient_system,':',recipient_user_id),CONCAT(sender_system,':',sender_user_id)) ref,MAX(id) last_id FROM aurora_internal_messages WHERE (sender_system='tms' AND sender_user_id={$mid}) OR (recipient_system='tms' AND recipient_user_id={$mid}) GROUP BY ref ORDER BY last_id DESC");if($r)while($x=$r->fetch_assoc())$refs[]=$x['ref'];$r=$this->db->query("SELECT CONCAT(sender_system,':',sender_user_id) ref,COUNT(*) total FROM aurora_internal_messages WHERE recipient_system='tms' AND recipient_user_id={$mid} AND read_at IS NULL GROUP BY sender_system,sender_user_id");if($r)while($x=$r->fetch_assoc())$unread[$x['ref']]=(int)$x['total'];jsonResponse(array('success'=>true,'data'=>array('contacts'=>$contacts,'conversation_refs'=>$refs,'unread'=>$unread)));}
        $input=$method==='GET'?$_GET:requestJson();$partner=$this->parsePartner(isset($input['partner'])?$input['partner']:'');$ps=$this->db->real_escape_string($partner['system']);$pid=(int)$partner['id'];
        if($method==='GET')jsonResponse(array('success'=>true,'data'=>$this->messages($mid,$ps,$pid)));
        if($method==='PUT'){$this->db->query("UPDATE aurora_internal_messages SET read_at=COALESCE(read_at,NOW()),updated_at=NOW() WHERE sender_system='{$ps}' AND sender_user_id={$pid} AND recipient_system='tms' AND recipient_user_id={$mid}");jsonResponse(array('success'=>true));}
        if($method==='POST'&&isset($input['operation'])&&$input['operation']==='react'){$messageId=(int)$input['message_id'];$emoji=(string)$input['emoji'];if(!in_array($emoji,$this->emojis,true))jsonResponse(array('success'=>false,'message'=>'Cảm xúc không hợp lệ.'),422);$thread=$this->thread($mid,$ps,$pid);$ok=$this->db->query("SELECT m.id FROM aurora_internal_messages m WHERE m.id={$messageId} AND {$thread} LIMIT 1");if(!$ok||!$ok->fetch_assoc())jsonResponse(array('success'=>false,'message'=>'Tin nhắn không thuộc cuộc trò chuyện này.'),404);$emojiSql=$this->emojiCodes[$emoji];$exists=$this->db->query("SELECT 1 FROM aurora_message_reactions WHERE message_id={$messageId} AND actor_system='tms' AND actor_user_id={$mid} AND emoji='{$emojiSql}'");if($exists&&$exists->num_rows)$this->db->query("DELETE FROM aurora_message_reactions WHERE message_id={$messageId} AND actor_system='tms' AND actor_user_id={$mid} AND emoji='{$emojiSql}'");else $this->db->query("INSERT INTO aurora_message_reactions VALUES({$messageId},'tms',{$mid},'{$emojiSql}',NOW())");jsonResponse(array('success'=>true));}
        if($method==='POST'){$content=trim((string)(isset($input['content'])?$input['content']:''));$topic=substr(trim((string)(isset($input['topic_tag'])?$input['topic_tag']:'')),0,80);$reply=(int)(isset($input['reply_to_id'])?$input['reply_to_id']:0);$file=isset($_FILES['attachment'])?$_FILES['attachment']:null;if($content===''&&!$file)jsonResponse(array('success'=>false,'message'=>'Hãy nhập nội dung hoặc chọn một tệp.'),422);if(strlen($content)>4000)jsonResponse(array('success'=>false,'message'=>'Tin nhắn không được vượt quá 4.000 ký tự.'),422);$upload=$file?$this->saveUpload($file):null;if($reply){$thread=$this->thread($mid,$ps,$pid);$q=$this->db->query("SELECT m.id FROM aurora_internal_messages m WHERE m.id={$reply} AND {$thread}");if(!$q||!$q->fetch_assoc())jsonResponse(array('success'=>false,'message'=>'Tin nhắn trả lời không hợp lệ.'),422);}$c=$this->db->real_escape_string($content);$t=$this->db->real_escape_string($topic);$type=$upload?$upload['type']:'text';$this->db->begin_transaction();$ok=$this->db->query("INSERT INTO aurora_internal_messages(sender_system,sender_user_id,recipient_system,recipient_user_id,content,topic_tag,reply_to_id,message_type,created_at,updated_at) VALUES('tms',{$mid},'{$ps}',{$pid},'{$c}','{$t}',".($reply?$reply:'NULL').",'{$type}',NOW(),NOW())");$messageId=(int)$this->db->insert_id;if($ok&&$upload){$o=$this->db->real_escape_string($upload['original']);$s=$this->db->real_escape_string($upload['stored']);$m=$this->db->real_escape_string($upload['mime']);$ok=$this->db->query("INSERT INTO aurora_message_attachments(message_id,original_name,stored_name,mime_type,size_bytes,created_at) VALUES({$messageId},'{$o}','{$s}','{$m}',{$upload['size']},NOW())");}if(!$ok){$this->db->rollback();if($upload)@unlink($this->uploadDir().DIRECTORY_SEPARATOR.$upload['stored']);jsonResponse(array('success'=>false,'message'=>'Không thể gửi tin nhắn.'),500);}$this->db->commit();jsonResponse(array('success'=>true,'data'=>array('id'=>$messageId)),201);}
        jsonResponse(array('success'=>false,'message'=>'Phương thức không được hỗ trợ.'),405);
    }
}
